import {SKILLS,SECTIONS,localDate,normalizeDiagnostic,normalizeRoutine,buildPlan} from './planner.js?v=8';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DAY_NAMES=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const pretty=date=>new Date(date+'T12:00:00Z').toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',timeZone:'UTC'});
export function createPlanner(context){
 const {getState,getData,getProfile,save,render,toast,openProfile,start}=context;
 const state=()=>getState(),data=()=>getData(),modal=()=>document.querySelector('#modal');
 const plan=()=>buildPlan({routine:state().routine,diagnostics:state().diagnostics||[],sessions:state().sessions,questions:data().questions,history:context.history()});
 function renderPlanner(){
  const s=state(),p=getProfile(),r=s.routine||{scope:s.section,minutes:30,days:[1,2,3,4,5],startDate:localDate(),testDate:p.testDate||''};
  let result=null,error='';if(s.routine){try{result=plan();}catch(e){error=e.message;}}
  const diagnostics=s.diagnostics||[],scope=r.scope==='Both'?SECTIONS:[r.scope];
  return `<div class="page-title"><div><h1>A routine that learns from your work.</h1><p>Use diagnostic results to choose a starting point. New practice adjusts the priorities, difficulty, and pace.</p></div><button class="secondary" data-action="diagnostic-add">Add diagnostic</button></div>
  <div class="planner-layout"><section class="routine-settings"><h2>Your weekly routine</h2><form id="routine-form"><label>Section focus<select name="scope">${['Math','Reading and Writing','Both'].map(section=>`<option ${section===r.scope?'selected':''}>${section}</option>`).join('')}</select></label><div class="routine-fields"><label>Minutes per study day<input name="minutes" type="number" min="15" max="120" step="5" required value="${r.minutes}"></label><label>Start date<input name="startDate" type="date" required value="${esc(r.startDate)}"></label><label>Next SAT date<input name="testDate" type="date" required value="${esc(r.testDate)}"></label></div><fieldset class="weekday-picker"><legend>Study days</legend>${DAY_NAMES.map((day,i)=>`<label><input type="checkbox" name="days" value="${i}" ${r.days.includes(i)?'checked':''}><span>${day.slice(0,3)}</span></label>`).join('')}</fieldset><p id="routine-error" class="form-error" role="alert">${esc(error)}</p><button class="primary" type="submit">${s.routine?'Update routine':'Build my plan'}</button><p class="field-note">The SAT date also updates your study profile. This plan does not predict a score or guarantee a target.</p></form></section>
  <section class="routine-notes"><h2>How your plan adapts</h2><p>Diagnostic misses get early attention. Recent answers count as independent only when they are correct, use no hints, and have a valid setup or reasoning.</p><p>Small samples stay tentative. Stronger skills receive less practice, while difficult skills return more often. Hard questions require stable work; pace targets require two stable sets.</p><p>Each day includes practice, review, and a short break in longer sessions. The stopwatch stays available for untimed work.</p><p class="small">Updates run locally in this browser. No AI connection is needed. Future sessions are rebuilt as you finish work; missed days do not pile up.</p></section></div>
  <div class="section-heading"><h2>Your diagnostic evidence</h2><label class="secondary import-label">Import diagnostic JSON<input id="diagnostic-import" type="file" accept="application/json,.json"></label></div>
  <p class="history-note" style="padding-top:0">Enter correct and total counts by skill for either section. The latest dated result for each skill is used, then adjusted with recent website practice. Screenshots and PDFs must be transcribed; this site does not read images.</p>
  ${diagnostics.length?diagnostics.map(d=>`<details class="diagnostic-summary"><summary><strong>${esc(d.label)}</strong><span>${esc(d.section)} · ${pretty(d.date)} · ${d.rows.reduce((n,row)=>n+row.correct,0)}/${d.rows.reduce((n,row)=>n+row.total,0)} ${d.label==='Saved diagnostic summary'?'mapped correct':'correct'}</span></summary><div class="table-wrap"><table><thead><tr><th>Reported skill</th><th>Practice category</th><th>Correct</th></tr></thead><tbody>${d.rows.map(row=>`<tr><td>${esc(row.reportedSkill||row.skill)}</td><td>${esc(row.skill)}</td><td>${row.correct}/${row.total}</td></tr>`).join('')}</tbody></table></div>${d.label==='Saved diagnostic summary'?'<p class="field-note">Imported from your saved skill summary. Broad categories group related subskills; “Graphs” is omitted because its exact skill is unknown. Use a new diagnostic to provide more precise evidence.</p>':''}<button class="text-button" data-action="diagnostic-delete" data-id="${esc(d.id)}">Remove this diagnostic from planning</button></details>`).join(''):'<div class="planner-empty"><h3>Bring in your starting point.</h3><p>Add a diagnostic by skill. You can also build a routine now and let your practice results establish priorities.</p><button class="secondary" data-action="diagnostic-add">Enter skill results</button></div>'}
  <details class="json-help"><summary>Diagnostic JSON format and template</summary><p class="small">Use the exact section and skill names shown in the entry form. Each row has a correct count and a total.</p><pre>${esc(JSON.stringify({schema:'sat-studio-diagnostic-v1',section:'Math',date:localDate(),label:'My diagnostic',rows:[{skill:'Linear Functions',correct:0,total:2}]},null,2))}</pre><button class="secondary" data-action="diagnostic-template">Download template</button></details>
  ${result?`<div class="section-heading"><h2>Your next study days</h2><span class="small muted">${result.completedCount} routine sessions complete</span></div><p class="history-note" style="padding-top:0">${esc(r.scope)} · ${r.minutes} minutes per day · ${r.days.map(i=>DAY_NAMES[i].slice(0,3)).join(', ')}. Review each missed or hinted question: rewrite the setup, name the trap, and state a recognition rule. Planned question time is an estimate.</p>${result.days.length?`<div class="study-agenda">${result.days.map((day,i)=>agendaRow(day,i)).join('')}</div><p class="field-note">Shows up to 28 study sessions within the next 12 weeks, ending before your SAT. More dates appear as time moves forward. Unattempted questions reserved in a paused set are kept out of new sessions.</p>`:`<div class="planner-empty"><h3>No study sessions can be scheduled.</h3><p>${r.testDate<=localDate()?'Your SAT date has passed. Enter your next test date above.':'Check the dates and weekdays above. Each practice session also needs at least three unused questions at an available difficulty; load more questions or finish paused sets if needed.'}</p></div>`}
  <div class="section-heading"><h2>Why these skills come first</h2><span class="small muted">For ${esc(r.scope)}</span></div><div class="table-wrap"><table><thead><tr><th>Skill</th><th>Evidence</th><th>Next step</th></tr></thead><tbody>${result.ranks.filter(item=>scope.includes(item.section)).slice(0,10).map(item=>`<tr><td><strong>${esc(item.skill)}</strong><small>${esc(item.section)}</small></td><td>${esc(item.reason)}</td><td>${item.stable?'Stretch, then check retention':'Untimed medium practice'}${item.practiceCount?'<small>Setup / reasoning included</small>':''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="planner-empty"><h2>Choose your days. Build your plan.</h2><p>Enter your next SAT date above so the calendar fits your available time.</p></div>'}`;
 }
 function agendaRow(day,index){
  const existing=day.existingId?state().sessions.find(s=>s.id===day.existingId):null;
  if(existing)return `<article class="agenda-row"><div class="agenda-date">${pretty(day.date)}</div><div class="agenda-content"><h3>${day.completed?'Completed':'Paused'} ${esc(day.section)} session</h3><p>${existing.records.length}/${existing.questionIds.length} questions attempted. ${day.completed?'Your future plan has adapted to these results.':'Resume to keep your work together.'}</p></div><button class="secondary" data-action="routine-start" data-date="${day.date}">${day.completed?'View results':'Resume'}</button></article>`;
  return `<article class="agenda-row"><div class="agenda-date">${pretty(day.date)}${index===0?'<span class="pill">Next session</span>':''}</div><div class="agenda-content"><small>${esc(day.section)} · ${day.difficulty} · ${day.timed?'Pace targets':'Untimed'}</small><h3>${esc(day.skills.join(', '))}</h3><p>${esc(day.reason)}</p><div class="routine-blocks"><span>${day.practiceMinutes}m practice · ${day.count} questions</span><span>${day.reviewMinutes}m review</span>${day.breakMinutes?`<span>${day.breakMinutes}m break</span>`:''}</div><p class="small muted">Target: ${day.target}.</p></div><button class="primary" data-action="routine-start" data-date="${day.date}">Start session</button></article>`;
 }
 function diagnosticForm(section=state().section){
  modal().innerHTML=`<div class="dialog-header"><h2>Add a diagnostic</h2><button class="secondary" data-action="close-modal" type="button">Close</button></div><p class="muted">Enter the counts shown in your results. Leave skills you were not tested on blank.</p><form id="diagnostic-form"><div class="routine-fields"><label>Diagnostic name<input name="label" type="text" maxlength="120" value="Diagnostic" required></label><label>Date taken<input name="date" type="date" max="${localDate()}" value="${localDate()}" required></label><label>SAT section<select name="section" id="diagnostic-section">${SECTIONS.map(value=>`<option ${section===value?'selected':''}>${value}</option>`).join('')}</select></label></div><p class="field-note">Changing sections clears unsaved skill counts. Add a separate diagnostic for each section.</p><div class="table-wrap diagnostic-entry"><table><thead><tr><th>Skill</th><th>Correct</th><th>Total tested</th></tr></thead><tbody>${SKILLS[section].map((skill,i)=>`<tr data-skill="${esc(skill)}"><td><label for="diag-c-${i}">${esc(skill)}</label></td><td><input id="diag-c-${i}" aria-label="${esc(skill)} correct" name="correct-${i}" type="number" min="0" max="1000" step="1"></td><td><input aria-label="${esc(skill)} total tested" name="total-${i}" type="number" min="1" max="1000" step="1"></td></tr>`).join('')}</tbody></table></div><p id="diagnostic-error" class="form-error" role="alert"></p><button class="primary" type="submit">Save diagnostic</button></form>`;
 }
 function addDiagnostic(input){
  const d=normalizeDiagnostic(input);if(d.date>localDate())throw Error('The diagnostic date cannot be in the future.');
  d.id=crypto.randomUUID();state().diagnostics ||= [];state().diagnostics.push(d);save();if(modal().open)modal().close();render();toast('Diagnostic saved. Your plan priorities have updated.');
 }
 function submit(event){
  const form=event.target;
  if(form.id==='routine-form'){
   event.preventDefault();try{const fields=new FormData(form);const routine=normalizeRoutine({scope:fields.get('scope'),minutes:fields.get('minutes'),startDate:fields.get('startDate'),testDate:fields.get('testDate'),days:fields.getAll('days')});if(routine.testDate<=localDate())throw Error('Enter a future SAT date to schedule study sessions.');state().routine=routine;state().profile={...getProfile(),testDate:routine.testDate};save();render();toast('Routine saved. Your schedule will adapt as you practice.');}catch(e){document.querySelector('#routine-error').textContent=e.message;}return true;
  }
  if(form.id==='diagnostic-form'){
   event.preventDefault();try{const fields=new FormData(form),section=fields.get('section');const rows=SKILLS[section].flatMap((skill,i)=>{const correct=fields.get('correct-'+i),total=fields.get('total-'+i);return correct!==''||total!==''?[{skill,correct,total}]:[];});addDiagnostic({section,date:fields.get('date'),label:fields.get('label'),rows});}catch(e){document.querySelector('#diagnostic-error').textContent=e.message;}return true;
  }
  return false;
 }
 async function change(event){
  if(event.target.id==='diagnostic-section'){diagnosticForm(event.target.value);return true;}
  if(event.target.id==='diagnostic-import'){
   try{const file=event.target.files[0];if(!file)return true;if(file.size>1000000)throw Error('Use a diagnostic JSON file smaller than 1 MB.');const input=JSON.parse(await file.text());if(input.schema!=='sat-studio-diagnostic-v1')throw Error('Use the diagnostic JSON template shown on the Study plan page.');addDiagnostic(input);}catch(e){toast(e.message||'Could not read the diagnostic.');}return true;
  }return false;
 }
 function click(action,target){
  if(action==='diagnostic-add'){diagnosticForm();modal().showModal();return true;}
  if(action==='diagnostic-delete'){state().diagnostics=state().diagnostics.filter(d=>d.id!==target.dataset.id);save();render();toast('Diagnostic removed from planning.');return true;}
  if(action==='diagnostic-template'){
   const section=state().section,payload={schema:'sat-studio-diagnostic-v1',section,date:localDate(),label:'My diagnostic',rows:[{skill:SKILLS[section][0],correct:0,total:2}]};
   const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='sat-diagnostic-template.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);return true;
  }
  if(action==='routine-start'){
   try{const d=plan().days.find(day=>day.date===target.dataset.date);if(!d)throw Error('This session changed. Refresh the plan and choose a session.');start(d);}catch(e){toast(e.message);}return true;
  }return false;
 }
 return {render:renderPlanner,submit,change,click};
}
